-- PyDex Seed Data (Standard Library Definitions)
BEGIN TRANSACTION;
INSERT OR IGNORE INTO modules (id, name, description) VALUES (1, 'builtins', 'Python Built-in Functions');
INSERT OR IGNORE INTO modules (id, name, description) VALUES (2, 'math', 'Python math standard library');
INSERT OR IGNORE INTO modules (id, name, description) VALUES (3, 'random', 'Python random standard library');
INSERT OR IGNORE INTO modules (id, name, description) VALUES (4, 'json', 'Python json standard library');
INSERT OR IGNORE INTO modules (id, name, description) VALUES (5, 'os', 'Python os standard library');
INSERT OR IGNORE INTO modules (id, name, description) VALUES (6, 'os.path', 'Python os.path standard library');
INSERT OR IGNORE INTO modules (id, name, description) VALUES (7, 'time', 'Python time standard library');
INSERT OR IGNORE INTO modules (id, name, description) VALUES (8, 're', 'Python re standard library');
INSERT OR IGNORE INTO modules (id, name, description) VALUES (9, 'shutil', 'Python shutil standard library');
INSERT OR IGNORE INTO modules (id, name, description) VALUES (10, 'csv', 'Python csv standard library');
INSERT OR IGNORE INTO modules (id, name, description) VALUES (11, 'hashlib', 'Python hashlib standard library');
INSERT OR IGNORE INTO modules (id, name, description) VALUES (12, 'datetime', 'Python datetime standard library');
INSERT OR IGNORE INTO modules (id, name, description) VALUES (13, 'collections', 'Python collections standard library');
INSERT OR IGNORE INTO modules (id, name, description) VALUES (14, 'itertools', 'Python itertools standard library');
INSERT OR IGNORE INTO modules (id, name, description) VALUES (15, 'functools', 'Python functools standard library');
INSERT OR IGNORE INTO modules (id, name, description) VALUES (16, 'pathlib', 'Python pathlib standard library');
INSERT OR IGNORE INTO modules (id, name, description) VALUES (17, 'copy', 'Python copy standard library');
INSERT OR IGNORE INTO modules (id, name, description) VALUES (18, 'sys', 'Python sys standard library');
INSERT OR IGNORE INTO functions (id, name, module_id, description, my_notes, discovered, is_important) VALUES (1, 'abs', 1, 'The `abs()` function returns the non‑negative magnitude of its argument, handling integers, floats, complex numbers (as their modulus), or any object that defines an `__abs__` method.', NULL, 0, 1);
INSERT OR IGNORE INTO functions (id, name, module_id, description, my_notes, discovered, is_important) VALUES (2, 'aiter', 1, 'The `aiter()` function returns an asynchronous iterator for a given asynchronous iterable by invoking its `__aiter__` method, providing a direct equivalent to calling `x.__aiter__()` without supporting a two‑argument form.', NULL, 0, 0);
INSERT OR IGNORE INTO functions (id, name, module_id, description, my_notes, discovered, is_important) VALUES (3, 'all', 1, 'The `all()` function returns True when every element in a given iterable evaluates to True (or when the iterable is empty), otherwise it returns False.', NULL, 0, 1);
INSERT OR IGNORE INTO functions (id, name, module_id, description, my_notes, discovered, is_important) VALUES (4, 'anext', 1, '`anext()` is an async function that returns an awaitable which, when awaited, yields the next item from an asynchronous iterator—or a provided default value if the iterator is exhausted.', NULL, 0, 0);
INSERT OR IGNORE INTO functions (id, name, module_id, description, my_notes, discovered, is_important) VALUES (5, 'any', 1, 'The any() function iterates through an iterable and returns True if it finds at least one element that evaluates as true, otherwise it returns False (including when the iterable is empty).', NULL, 0, 1);
INSERT OR IGNORE INTO functions (id, name, module_id, description, my_notes, discovered, is_important) VALUES (6, 'ascii', 1, 'The ascii() function returns a printable string representation of an object like repr() but escapes any non‑ASCII characters using \x, \u, or \U escape sequences.', NULL, 0, 0);
INSERT OR IGNORE INTO functions (id, name, module_id, description, my_notes, discovered, is_important) VALUES (7, 'bin', 1, 'The bin() function converts an integer (or an object defining __index__) into its binary string representation, optionally prefixed with “0b”.', NULL, 0, 0);
INSERT OR IGNORE INTO functions (id, name, module_id, description, my_notes, discovered, is_important) VALUES (8, 'bool', 1, 'The bool() function converts its argument (or defaults to False if omitted) to a Boolean value, returning True for any truthy input and False for falsy ones.', NULL, 0, 0);
INSERT OR IGNORE INTO functions (id, name, module_id, description, my_notes, discovered, is_important) VALUES (9, 'breakpoint', 1, 'The `breakpoint()` function provides a convenient way to pause program execution and enter the debugger (by default `pdb.set_trace()`) at the call site, while allowing the debugger hook to be customized via `sys.breakpointhook` or the `PYTHONBREAKPOINT` environment variable.', NULL, 0, 0);
INSERT OR IGNORE INTO functions (id, name, module_id, description, my_notes, discovered, is_important) VALUES (10, 'bytearray', 1, 'The `bytearray()` function creates a mutable sequence of bytes, optionally initializing it from a string (with encoding), an integer size of zero-filled bytes, a buffer, or an iterable of integer values 0‑255.', NULL, 0, 0);
INSERT OR IGNORE INTO functions (id, name, module_id, description, my_notes, discovered, is_important) VALUES (11, 'bytes', 1, 'The `bytes()` function creates an immutable sequence of integers (0–255) from various inputs, providing a read‑only version of a bytearray with the same indexing, slicing, and non‑mutating methods.', NULL, 0, 0);
INSERT OR IGNORE INTO functions (id, name, module_id, description, my_notes, discovered, is_important) VALUES (12, 'callable', 1, 'The callable() function checks whether an object can be invoked like a function, returning True for callable objects (including classes and instances with a __call__ method) and False otherwise.', NULL, 0, 0);
INSERT OR IGNORE INTO functions (id, name, module_id, description, my_notes, discovered, is_important) VALUES (13, 'chr', 1, 'The chr() function converts an integer Unicode code point (0‑0x10FFFF) into the corresponding one‑character string, raising ValueError for out‑of‑range values.', NULL, 0, 0);
INSERT OR IGNORE INTO functions (id, name, module_id, description, my_notes, discovered, is_important) VALUES (14, 'classmethod', 1, 'classmethod() converts a regular function into a method that receives the owning class as its first argument, allowing it to be invoked on the class or its instances.', NULL, 0, 0);
INSERT OR IGNORE INTO functions (id, name, module_id, description, my_notes, discovered, is_important) VALUES (15, 'compile', 1, 'The `compile()` function transforms source code given as a string, bytes, or AST into a code object (or AST) according to the specified mode (''exec'', ''eval'', or ''single'') so it can be executed by `exec()` or `eval()`.', NULL, 0, 1);
INSERT OR IGNORE INTO functions (id, name, module_id, description, my_notes, discovered, is_important) VALUES (16, 'complex', 1, 'The `complex()` function converts a string or numeric input (or separate real and imaginary parts) into a Python complex number, handling various formats and falling back to appropriate numeric conversion methods.', NULL, 0, 0);
INSERT OR IGNORE INTO functions (id, name, module_id, description, my_notes, discovered, is_important) VALUES (17, 'delattr', 1, 'delattr() removes a specified attribute from an object, equivalent to executing a delete statement like “del object.attribute”.', NULL, 0, 0);
INSERT OR IGNORE INTO functions (id, name, module_id, description, my_notes, discovered, is_important) VALUES (18, 'dict', 1, 'The dict() function creates and returns a new dictionary object, optionally initializing it from mappings, keyword arguments, or iterable key‑value pairs.', NULL, 0, 1);
INSERT OR IGNORE INTO functions (id, name, module_id, description, my_notes, discovered, is_important) VALUES (19, 'dir', 1, 'The dir() function returns a sorted list of attribute names accessible in the current local scope when called without arguments, or the valid attribute names of a given object—using its __dir__ method if present, otherwise gathering from its __dict__, type, and inheritance hierarchy.', NULL, 0, 0);
INSERT OR IGNORE INTO functions (id, name, module_id, description, my_notes, discovered, is_important) VALUES (20, 'divmod', 1, 'The divmod() function takes two numbers and returns a tuple containing their integer quotient and remainder, matching the results of floor division and modulo while ensuring the remainder’s sign follows the divisor and the relationship q * b + r ≈ a holds.', NULL, 0, 0);
INSERT OR IGNORE INTO functions (id, name, module_id, description, my_notes, discovered, is_important) VALUES (21, 'enumerate', 1, '`enumerate()` creates an iterator that yields pairs of an index (starting from a given value, default 0) and each element from the provided iterable.', NULL, 0, 1);
INSERT OR IGNORE INTO functions (id, name, module_id, description, my_notes, discovered, is_important) VALUES (22, 'eval', 1, 'The eval() function parses and evaluates a given Python expression (or compiled code object) using optional global and local namespaces and returns its result, while warning that executing untrusted code is insecure.', NULL, 0, 0);
INSERT OR IGNORE INTO functions (id, name, module_id, description, my_notes, discovered, is_important) VALUES (23, 'exec', 1, 'exec() dynamically executes a string or code object as Python statements within optional global and local namespaces, returning None.', NULL, 0, 0);
INSERT OR IGNORE INTO functions (id, name, module_id, description, my_notes, discovered, is_important) VALUES (24, 'filter', 1, 'The filter() function creates an iterator that yields only those items from an iterable for which a given function returns true (or, if the function is None, those items that are truthy).', NULL, 0, 1);
INSERT OR IGNORE INTO functions (id, name, module_id, description, my_notes, discovered, is_important) VALUES (25, 'float', 1, 'The `float()` function converts a given numeric value or properly formatted string into a floating‑point number, optionally handling signs, whitespace, underscores, infinities, NaN, and delegating to an object''s `__float__` or `__index__` method, returning 0.0 when called without arguments.', NULL, 0, 0);
INSERT OR IGNORE INTO functions (id, name, module_id, description, my_notes, discovered, is_important) VALUES (26, 'format', 1, 'The `format()` function returns a string representation of a value formatted according to a given format specification, delegating the work to the value’s type-specific `__format__` method.', NULL, 0, 0);
INSERT OR IGNORE INTO functions (id, name, module_id, description, my_notes, discovered, is_important) VALUES (27, 'frozenset', 1, '`frozenset()` creates an immutable set object, optionally populated with elements from a given iterable.', NULL, 0, 0);
INSERT OR IGNORE INTO functions (id, name, module_id, description, my_notes, discovered, is_important) VALUES (28, 'getattr', 1, '`getattr()` retrieves the value of a specified attribute from an object, optionally returning a default value instead of raising an AttributeError if the attribute does not exist.', NULL, 0, 0);
INSERT OR IGNORE INTO functions (id, name, module_id, description, my_notes, discovered, is_important) VALUES (29, 'globals', 1, '`globals()` returns the dictionary representing the current module’s global namespace, reflecting the symbols defined at the module level when the function was created, regardless of where it is later called.', NULL, 0, 0);
INSERT OR IGNORE INTO functions (id, name, module_id, description, my_notes, discovered, is_important) VALUES (30, 'hasattr', 1, '`hasattr()` checks whether a given object possesses an attribute with a specified name and returns True if it exists, otherwise False.', NULL, 0, 0);
INSERT OR IGNORE INTO functions (id, name, module_id, description, my_notes, discovered, is_important) VALUES (31, 'hash', 1, 'The `hash()` function computes an integer hash value for an object, enabling fast key comparisons in dictionaries and other hash-based collections.', NULL, 0, 0);
INSERT OR IGNORE INTO functions (id, name, module_id, description, my_notes, discovered, is_important) VALUES (32, 'help', 1, 'The built‑in help() function launches Python’s interactive help system, displaying documentation for modules, functions, classes, methods, keywords, or any object based on the provided argument or starting an interactive help session when called without arguments.', NULL, 0, 0);
INSERT OR IGNORE INTO functions (id, name, module_id, description, my_notes, discovered, is_important) VALUES (33, 'hex', 1, 'The `hex()` function returns a string representing a given integer in lowercase hexadecimal format prefixed with “0x”, handling negative numbers with a leading minus sign and requiring the argument to be an int or implement `__index__()`.', NULL, 0, 0);
INSERT OR IGNORE INTO functions (id, name, module_id, description, my_notes, discovered, is_important) VALUES (34, 'id', 1, 'The `id()` function returns a unique integer representing the object''s identity, which remains constant for the object''s lifetime (in CPython it is the object''s memory address).', NULL, 0, 0);
INSERT OR IGNORE INTO functions (id, name, module_id, description, my_notes, discovered, is_important) VALUES (35, 'input', 1, 'The `input()` function optionally prints a prompt, reads a line from standard input, strips the trailing newline, returns the resulting string, and raises EOFError if end‑of‑file is encountered.', NULL, 0, 1);
INSERT OR IGNORE INTO functions (id, name, module_id, description, my_notes, discovered, is_important) VALUES (36, 'int', 1, 'int() converts a given number, string, bytes, or bytearray (optionally with a specified base) into an integer object, using __int__ or __index__ methods when available, and returns 0 when called with no arguments.', NULL, 0, 1);
INSERT OR IGNORE INTO functions (id, name, module_id, description, my_notes, discovered, is_important) VALUES (37, 'isinstance', 1, '`isinstance()` checks whether a given object belongs to a specified type, subclass, or any type within a tuple or Union, returning True if it does and False otherwise.', NULL, 0, 1);
INSERT OR IGNORE INTO functions (id, name, module_id, description, my_notes, discovered, is_important) VALUES (38, 'issubclass', 1, '`issubclass()` returns True if a given class is a subclass—direct, indirect, virtual, or itself—of the specified classinfo (which may be a class, a tuple of classes, or a Union type), otherwise it raises a TypeError.', NULL, 0, 0);
INSERT OR IGNORE INTO functions (id, name, module_id, description, my_notes, discovered, is_important) VALUES (39, 'iter', 1, 'The iter() function returns an iterator either by converting an iterable object into an iterator when called with one argument, or by repeatedly calling a zero‑argument callable until it returns a sentinel value when called with two arguments.', NULL, 0, 0);
INSERT OR IGNORE INTO functions (id, name, module_id, description, my_notes, discovered, is_important) VALUES (40, 'len', 1, 'The `len()` function returns the number of items in a sequence or collection, raising an OverflowError if the length exceeds `sys.maxsize`.', NULL, 0, 1);
INSERT OR IGNORE INTO functions (id, name, module_id, description, my_notes, discovered, is_important) VALUES (41, 'list', 1, 'The list() function creates a new mutable list object, optionally converting an iterable’s elements into a list.', NULL, 0, 1);
INSERT OR IGNORE INTO functions (id, name, module_id, description, my_notes, discovered, is_important) VALUES (42, 'locals', 1, '`locals()` returns a mapping of the current local variable names to their bound objects, allowing inspection (and, in some scopes, modification) of the local symbol table.', NULL, 0, 0);
INSERT OR IGNORE INTO functions (id, name, module_id, description, my_notes, discovered, is_important) VALUES (43, 'map', 1, '`map()` returns an iterator that lazily applies a given function to each element of one or more iterables in parallel, stopping at the shortest iterable (or raising a ValueError if `strict=True` and any iterable ends early).', NULL, 0, 1);
INSERT OR IGNORE INTO functions (id, name, module_id, description, my_notes, discovered, is_important) VALUES (44, 'max', 1, 'The `max()` function returns the greatest element from a single iterable or from multiple given arguments, optionally using a key function for ordering and a default value for empty iterables.', NULL, 0, 1);
INSERT OR IGNORE INTO functions (id, name, module_id, description, my_notes, discovered, is_important) VALUES (45, 'memoryview', 1, '`memoryview()` creates a lightweight, read‑only or writable view onto an existing buffer object, allowing efficient access to its underlying memory without copying the data.', NULL, 0, 0);
INSERT OR IGNORE INTO functions (id, name, module_id, description, my_notes, discovered, is_important) VALUES (46, 'min', 1, 'The min() function returns the smallest element from a single iterable or the smallest of multiple arguments, optionally using a key function for ordering and a default value to return when the iterable is empty.', NULL, 0, 1);
INSERT OR IGNORE INTO functions (id, name, module_id, description, my_notes, discovered, is_important) VALUES (47, 'next', 1, 'The `next()` function returns the subsequent element from an iterator by invoking its `__next__()` method, optionally providing a default value to return instead of raising `StopIteration` when the iterator is exhausted.', NULL, 0, 0);
INSERT OR IGNORE INTO functions (id, name, module_id, description, my_notes, discovered, is_important) VALUES (48, 'object', 1, 'The `object()` function creates a minimal, featureless instance of the ultimate base class for all Python objects, taking no arguments and providing only the core behavior shared by every class.', NULL, 0, 0);
INSERT OR IGNORE INTO functions (id, name, module_id, description, my_notes, discovered, is_important) VALUES (49, 'oct', 1, 'The oct() function returns a string representing an integer in octal notation, prefixed with “0o” (or a leading minus sign for negative values).', NULL, 0, 0);
INSERT OR IGNORE INTO functions (id, name, module_id, description, my_notes, discovered, is_important) VALUES (50, 'open', 1, 'The open() function opens a specified file (or file descriptor) with a given mode and optional parameters, returning a corresponding file object for reading, writing, or appending, and raises an OSError if the operation fails.', NULL, 0, 1);
INSERT OR IGNORE INTO functions (id, name, module_id, description, my_notes, discovered, is_important) VALUES (51, 'ord', 1, 'The ord() function takes a single-character string or a one‑byte bytes/bytearray object and returns its Unicode code point or byte value as an integer.', NULL, 0, 0);
INSERT OR IGNORE INTO functions (id, name, module_id, description, my_notes, discovered, is_important) VALUES (52, 'pow', 1, 'The pow() function returns base raised to the exponent, optionally computing the result modulo a third integer argument more efficiently than using the ** operator or a separate modulus operation.', NULL, 0, 1);
INSERT OR IGNORE INTO functions (id, name, module_id, description, my_notes, discovered, is_important) VALUES (53, 'print', 1, 'The `print()` function outputs one or more objects as text to a specified stream (defaulting to standard output), separating them with a given separator, ending with a specified string, and optionally flushing the stream.', NULL, 0, 1);
INSERT OR IGNORE INTO functions (id, name, module_id, description, my_notes, discovered, is_important) VALUES (54, 'property', 1, 'The `property()` function creates a managed attribute by wrapping optional getter, setter, and deleter callables (and an optional docstring) into a descriptor that controls access to a class attribute.', NULL, 0, 0);
INSERT OR IGNORE INTO functions (id, name, module_id, description, my_notes, discovered, is_important) VALUES (55, 'getter', 1, 'The `getter()` function retrieves and returns a specific value or object from its surrounding context, such as a variable, attribute, or data structure, based on the parameters or logic defined within it.', NULL, 0, 0);
INSERT OR IGNORE INTO functions (id, name, module_id, description, my_notes, discovered, is_important) VALUES (56, 'setter', 1, 'The `setter()` function assigns a new value to a specified attribute of an object, optionally performing validation or additional processing before updating the attribute.', NULL, 0, 0);
INSERT OR IGNORE INTO functions (id, name, module_id, description, my_notes, discovered, is_important) VALUES (57, 'deleter', 1, 'The `deleter()` method creates and returns a new property object identical to the original but with its fdel accessor replaced by the function it decorates, enabling deletion behavior for that property.', NULL, 0, 0);
INSERT OR IGNORE INTO functions (id, name, module_id, description, my_notes, discovered, is_important) VALUES (58, '__name__', 1, '`__name__` is a special attribute that stores the name of a module, class, or function, allowing the code to identify its own context and enabling behavior such as conditional execution when the script is run directly versus imported.', NULL, 0, 0);
INSERT OR IGNORE INTO functions (id, name, module_id, description, my_notes, discovered, is_important) VALUES (59, 'range', 1, 'The range() construct generates an immutable sequence of integers defined by a start, stop, and optional step, enabling efficient iteration and slicing without creating a list in memory.', NULL, 0, 1);
INSERT OR IGNORE INTO functions (id, name, module_id, description, my_notes, discovered, is_important) VALUES (60, 'repr', 1, 'repr() returns a string that provides an official, unambiguous representation of an object, ideally one that can be passed to eval() to recreate the same object.', NULL, 0, 0);
INSERT OR IGNORE INTO functions (id, name, module_id, description, my_notes, discovered, is_important) VALUES (61, 'reversed', 1, 'The `reversed()` function returns an iterator that yields the elements of a given sequence or iterable in the opposite order, requiring the object to implement a `__reversed__()` method or support the sequence protocol with `__len__()` and integer-indexed `__getitem__()`.', NULL, 0, 0);
INSERT OR IGNORE INTO functions (id, name, module_id, description, my_notes, discovered, is_important) VALUES (62, 'round', 1, 'The round() function returns a number rounded to the specified number of decimal places (or to the nearest integer if no precision is given), using “bankers rounding” where ties are broken toward the even value.', NULL, 0, 1);
INSERT OR IGNORE INTO functions (id, name, module_id, description, my_notes, discovered, is_important) VALUES (63, 'set', 1, 'The `set()` function creates and returns a new mutable set object, optionally initializing it with unique elements drawn from a given iterable.', NULL, 0, 1);
INSERT OR IGNORE INTO functions (id, name, module_id, description, my_notes, discovered, is_important) VALUES (64, 'setattr', 1, 'setattr() assigns a specified value to a named attribute of an object, creating the attribute if it does not already exist.', NULL, 0, 0);
INSERT OR IGNORE INTO functions (id, name, module_id, description, my_notes, discovered, is_important) VALUES (65, 'slice', 1, 'The `slice()` function creates a slice object that defines a range of indices (with optional start, stop, and step values) which can be used for slicing sequences, and these objects are now hashable when their components are hashable.', NULL, 0, 0);
INSERT OR IGNORE INTO functions (id, name, module_id, description, my_notes, discovered, is_important) VALUES (66, 'start', 1, 'The `start()` function initializes the object''s read‑only attributes with the provided arguments (or their defaults), enabling NumPy and other libraries to access these values.', NULL, 0, 0);
INSERT OR IGNORE INTO functions (id, name, module_id, description, my_notes, discovered, is_important) VALUES (67, 'sorted', 1, 'The sorted() function returns a new list containing the elements of an iterable ordered according to optional key and reverse parameters without modifying the original iterable.', NULL, 0, 1);
INSERT OR IGNORE INTO functions (id, name, module_id, description, my_notes, discovered, is_important) VALUES (68, 'staticmethod', 1, 'staticmethod() converts a regular function into a static method that can be called on a class or its instances without receiving an implicit first argument.', NULL, 0, 0);
INSERT OR IGNORE INTO functions (id, name, module_id, description, my_notes, discovered, is_important) VALUES (69, 'str', 1, 'The `str()` function converts any given object into its string representation, returning that value as a `str` type.', NULL, 0, 1);
INSERT OR IGNORE INTO functions (id, name, module_id, description, my_notes, discovered, is_important) VALUES (70, 'sum', 1, 'The `sum()` function adds a start value to each numeric item of an iterable from left to right and returns the total.', NULL, 0, 1);
INSERT OR IGNORE INTO functions (id, name, module_id, description, my_notes, discovered, is_important) VALUES (71, 'super', 1, 'super() returns a proxy that searches the method resolution order after a specified class (or the current class when used with no arguments) to delegate calls to inherited or sibling methods, enabling explicit parent method access and cooperative multiple inheritance.', NULL, 0, 1);
INSERT OR IGNORE INTO functions (id, name, module_id, description, my_notes, discovered, is_important) VALUES (72, 'tuple', 1, 'The `tuple()` function creates an immutable ordered collection by converting an iterable (or returning an empty tuple when called without arguments).', NULL, 0, 0);
INSERT OR IGNORE INTO functions (id, name, module_id, description, my_notes, discovered, is_important) VALUES (73, 'type', 1, 'The type() built‑in either returns the type object of a given value (one‑argument form) or dynamically creates a new class when supplied with a name, bases tuple, and dictionary of attributes (three‑argument form).', NULL, 0, 1);
INSERT OR IGNORE INTO functions (id, name, module_id, description, my_notes, discovered, is_important) VALUES (74, 'vars', 1, 'vars() returns an object’s __dict__ attribute (or the current local symbol table when called without arguments), raising a TypeError if the given object lacks a __dict__ (e.g., due to __slots__).', NULL, 0, 0);
INSERT OR IGNORE INTO functions (id, name, module_id, description, my_notes, discovered, is_important) VALUES (75, 'zip', 1, 'zip() creates a lazy iterator that aggregates elements from multiple iterables into tuples, pairing the i‑th items together (stopping at the shortest iterable unless strict=True is used).', NULL, 0, 1);
INSERT OR IGNORE INTO functions (id, name, module_id, description, my_notes, discovered, is_important) VALUES (76, '__import__', 1, 'It is the low‑level built‑in that the import statement calls to locate and load a module (optionally using package context, fromlist, and relative‑import level) and returns either the top‑level package or the requested module, but direct use is discouraged in favor of importlib.import_module().', NULL, 0, 0);
INSERT OR IGNORE INTO functions (id, name, module_id, description, my_notes, discovered, is_important) VALUES (77, 'acos', 2, 'Return the arc cosine (measured in radians) of x.', NULL, 0, 0);
INSERT OR IGNORE INTO functions (id, name, module_id, description, my_notes, discovered, is_important) VALUES (78, 'acosh', 2, 'Return the inverse hyperbolic cosine of x.', NULL, 0, 0);
INSERT OR IGNORE INTO functions (id, name, module_id, description, my_notes, discovered, is_important) VALUES (79, 'asin', 2, 'Return the arc sine (measured in radians) of x.', NULL, 0, 0);
INSERT OR IGNORE INTO functions (id, name, module_id, description, my_notes, discovered, is_important) VALUES (80, 'asinh', 2, 'Return the inverse hyperbolic sine of x.', NULL, 0, 0);
INSERT OR IGNORE INTO functions (id, name, module_id, description, my_notes, discovered, is_important) VALUES (81, 'atan', 2, 'Return the arc tangent (measured in radians) of x.', NULL, 0, 0);
INSERT OR IGNORE INTO functions (id, name, module_id, description, my_notes, discovered, is_important) VALUES (82, 'atan2', 2, 'Return the arc tangent (measured in radians) of y/x.', NULL, 0, 0);
INSERT OR IGNORE INTO functions (id, name, module_id, description, my_notes, discovered, is_important) VALUES (83, 'atanh', 2, 'Return the inverse hyperbolic tangent of x.', NULL, 0, 0);
INSERT OR IGNORE INTO functions (id, name, module_id, description, my_notes, discovered, is_important) VALUES (84, 'cbrt', 2, 'Return the cube root of x.', NULL, 0, 0);
INSERT OR IGNORE INTO functions (id, name, module_id, description, my_notes, discovered, is_important) VALUES (85, 'ceil', 2, 'Return the ceiling of x as an Integral.', NULL, 0, 1);
INSERT OR IGNORE INTO functions (id, name, module_id, description, my_notes, discovered, is_important) VALUES (86, 'comb', 2, 'Number of ways to choose k items from n items without repetition and without order.', NULL, 0, 0);
INSERT OR IGNORE INTO functions (id, name, module_id, description, my_notes, discovered, is_important) VALUES (87, 'copysign', 2, 'Return a float with the magnitude (absolute value) of x but the sign of y.', NULL, 0, 0);
INSERT OR IGNORE INTO functions (id, name, module_id, description, my_notes, discovered, is_important) VALUES (88, 'cos', 2, 'Return the cosine of x (measured in radians).', NULL, 0, 1);
INSERT OR IGNORE INTO functions (id, name, module_id, description, my_notes, discovered, is_important) VALUES (89, 'cosh', 2, 'Return the hyperbolic cosine of x.', NULL, 0, 0);
INSERT OR IGNORE INTO functions (id, name, module_id, description, my_notes, discovered, is_important) VALUES (90, 'degrees', 2, 'Convert angle x from radians to degrees.', NULL, 0, 1);
INSERT OR IGNORE INTO functions (id, name, module_id, description, my_notes, discovered, is_important) VALUES (91, 'dist', 2, 'Return the Euclidean distance between two points p and q.', NULL, 0, 0);
INSERT OR IGNORE INTO functions (id, name, module_id, description, my_notes, discovered, is_important) VALUES (92, 'erf', 2, 'Error function at x.', NULL, 0, 0);
INSERT OR IGNORE INTO functions (id, name, module_id, description, my_notes, discovered, is_important) VALUES (93, 'erfc', 2, 'Complementary error function at x.', NULL, 0, 0);
